 {view==='sources'&&<><div className="source-help"><p><strong>Supported structured input:</strong> parameters with value, unit, method, batch, limits and basis. Uploaded originals are stored with SHA-256 and permissions.</p>{!state.sources.length&&<button className="button small secondary" onClick={()=>form('Load synthetic CMC fixtures',[],async()=>{if(demo){setState(await seedSynthetic());setModal(null);}else await act({action:'seedSynthetic'});},'Three synthetic sources contain one deliberate assay conflict and one explicit mass-unit conversion. They are not company records.',true,'Load synthetic case')}><FlaskConical size={15}/> Load synthetic case</button>}</div>{!state.sources.length?<Empty title="No sources yet.">Add a permitted source or load the labelled synthetic case. Unsupported and ambiguous inputs will remain visible.</Empty>:<div className="source-grid">{state.sources.filter(matches).map((s:any)=><article className="panel source-card" key={s.id}><div className="source-visual"><FileText size={38}/><span>{s.type.split('/').pop()?.toUpperCase()}</span><small>{s.dataLabel}</small></div><div className="source-card-copy"><div className="row-between"><span className="eyebrow">REVISION {s.version}</span><Status value={s.status}/></div><h3>{s.name}</h3><p>{s.permission}</p><small className="mono">SHA-256 {s.hash.slice(0,18)}…</small>{s.failure&&<p className="failure-copy">{s.failure}</p>}<div className="row-actions"><button className="button small secondary" onClick={()=>original(s)}>Original <ArrowUpRight size={14}/></button>{!demo&&s.status!=='SUPERSEDED'&&<button className="button small secondary" onClick={()=>replaceOriginal(s)} disabled={busy||!canAuthor}>New original revision</button>}<button className="button small" onClick={()=>run({action:s.type.includes('openxmlformats')||['application/xml','text/xml'].includes(s.type)?'documentExtract':'extract',id:s.id})} disabled={busy||!actorCan(role,'extract')||s.status==='SUPERSEDED'}>{s.status==='PARSED'?'Check extraction':'Extract'} <ScanLine size={14}/></button>{['application/pdf','image/png','image/jpeg'].includes(s.type)&&s.status!=='PARSED'&&<button className="button small secondary" disabled={demo||busy||!canWrite} onClick={()=>form('Authorize document candidate extraction',[],async()=>{await act({action:'visionExtract',id:s.id,providerPermission:true});},'Original source bytes are sent only to the configured document/vision provider. Output stays NEEDS REVIEW until you inspect the original page. Missing configuration creates a visible HOLD.',true,'Authorize bounded extraction')}>Vision candidate</button>}</div></div></article>)}</div>}</>}
 {view==='extraction'&&<><div className="toolbar"><label className="search-field"><Search size={16}/><input aria-label="Search fields" placeholder="Search parameter, batch or method…" value={search} onChange={e=>setSearch(e.target.value)}/></label><span>{activeFields.length} current field records</span></div>{state.fields.length?fieldTable(state.fields):<Empty title="No extracted fields yet.">Add a structured source, then run extraction.</Empty>}</>}
 {view==='conflicts'&&<><div className="stats-grid three"><div className="stat-card"><span>Open conflicts</span><strong>{ready.openConflicts}</strong><small>Competing source values</small></div><div className="stat-card"><span>Required gaps</span><strong>{gaps.length}</strong><small>Missing remains missing</small></div><div className="stat-card"><span>Value anomalies</span><strong>{ready.anomalies}</strong><small>No autonomous disposition</small></div></div>{gaps.length>0&&<section className="panel"><h3>Required evidence missing</h3><p>{gaps.join(', ')}</p><button className="button small secondary" onClick={()=>navigate('sources')}>Add supporting source</button></section>}<div className="stack">{state.conflicts.map((c:any)=><article className="panel" key={c.id}><div className="panel-heading"><h3 className="capitalize">{c.parameter} · {c.batch}</h3><Status value={c.status}/></div><div className="competing-values">{c.fieldIds.map((id:string)=>{const f=state.fields.find((f:any)=>f.id===id);return <div key={id}><span>{sourceOf(f)?.name}</span><strong>{f.value} {f.unit}</strong><small>{f.method} · source v{f.sourceVersion}</small><button className="inline-link" onClick={()=>original(sourceOf(f))}>Inspect original <ArrowUpRight size={13}/></button>{c.status==='OPEN'&&<button className="button small secondary" onClick={()=>form('Resolve competing evidence',[{name:'reason',label:'Reason this source is authoritative',type:'textarea'}],async v=>{await act({action:'resolveConflict',id:c.id,selectedId:id,...v});},`Keep ${f.value} ${f.unit} from ${sourceOf(f)?.name}. Other competing candidates will be rejected with your recorded reason.`)} disabled={!canWrite}>Select this evidence</button>}</div>;})}</div>{c.reason&&<p className="subnote">Resolution: {c.reason}</p>}</article>)}</div>{!state.conflicts.length&&!gaps.length&&<Empty title="No current conflict or required gap.">Technical checks found none in the recorded source set. Scientific review remains required.</Empty>}{ready.anomalies>0&&fieldTable(activeFields.filter((f:any)=>f.issues?.includes('OUTSIDE_RECORDED_LIMIT')))}</>}
 {view==='batches'&&<><p className="callout">Comparisons are descriptive. Matching values or recorded limits do not establish clinical equivalence, batch release or regulatory acceptability.</p><div className="stack">{comparison(state).map((c:any)=><article className="panel" key={c.parameter}><div className="panel-heading"><h3 className="capitalize">{c.parameter}</h3><Status value={c.comparable?'COMPARABLE_CONTEXT':'NEEDS_REVIEW'}/></div><p>{c.reason}</p><div className="batch-bars">{c.fields.map((f:any)=><div key={f.id}><span>{f.batch}</span><div className="bar-track"><i style={{width:`${f.value===null?0:Math.max(4,Math.min(100,Math.abs(f.value)/(Math.abs(c.max)||100)*92))}%`}}/></div><strong>{f.value??'—'} {f.unit}</strong><small>{f.method}</small></div>)}</div><div className="comparison-footer"><span>Range: {c.comparable?`${c.min} – ${c.max}`:'NOT COMPARABLE'}</span><span>Mean: {c.mean===null?'NOT MEASURED':Number(c.mean.toFixed(4))}</span><button className="inline-link" onClick={()=>navigate('extraction')}>Inspect source fields <ArrowRight size={14}/></button></div></article>)}</div>{!state.fields.length&&<Empty title="No batch evidence yet.">Extract fields with explicit batch, method, unit and limits.</Empty>}</>}
 {view==='graph'&&<EvidenceGraph state={state} inspect={inspect} original={original} initialSelected={selected}/>}
 {view==='drafts'&&<div className="callout"><strong>Authoring mode:</strong> deterministic source templates are available. AI-assisted candidate drafting requires a pinned server-side provider.<button className="button small secondary" disabled={demo||!canWrite} onClick={()=>form('Request AI-assisted draft',[],async()=>{await act({action:'aiDraft',providerPermission:true,title:'AI-assisted quality draft',section:'3.2.P'});},'Only approved facts are transmitted to the configured AI provider. No tools or autonomous decisions are authorized. If configuration is absent, the task is recorded as HOLD.',true,'Authorize bounded AI task')}>AI-assisted candidate</button></div>}
 {view==='drafts'&&(state.drafts.length?draftCards(state.drafts):<Empty title="Create a draft from approved facts.">Resolve conflicts, review supported facts and create a 3.2.S or 3.2.P candidate. Unsupported sections stay missing.</Empty>)}
 {view==='reviews'&&<><div className="callout"><strong>Author ≠ independent QC ≠ human approver.</strong> Technical QC runs under a separate rules principal. Your decision stays bound to the candidate revision; source changes invalidate dependent approvals.</div><section className="panel"><div className="panel-heading"><h3>Field candidates</h3><span>{activeFields.filter((f:any)=>f.status!=='APPROVED').length} awaiting disposition</span></div>{activeFields.length?fieldTable(activeFields):<p>No extracted field candidates yet.</p>}</section><h2 className="subheading">Draft review</h2>{draftCards(state.drafts)}</>}
 {view==='changes'&&<><section className="panel"><div className="panel-heading"><div><span className="eyebrow">CONTROLLED SOURCE REVISION</span><h3>Inspect the blast radius before changing.</h3></div></div><div className="source-selection">{state.sources.filter((s:any)=>s.status!=='SUPERSEDED').map((s:any)=><div key={s.id}><FileText size={20}/><span>{s.name}<small>Current revision {s.version}</small></span><button className="button small secondary" onClick={()=>inspect('Simulated dependency impact',<pre>{JSON.stringify(blastRadius(state,s.id),null,2)}</pre>)}>Simulate</button><button className="button small" onClick={()=>{if(!['application/json','text/csv','text/plain'].includes(s.type)){if(!demo)replaceOriginal(s);else inspect('Original revision requires storage',<p>Open a persistent workspace to upload a new original revision.</p>);return;}form('Register a revised source',[{name:'reason',label:'Material change reason',type:'textarea'},{name:'text',label:'New original structured content',type:'textarea',value:s.text}],async v=>{await act({action:'change',id:s.id,...v});},'The original revision stays historical. Only recorded dependent fields, drafts and approvals become stale. Extract and review the new revision before use.');}} disabled={!canWrite}>New revision</button></div>)}</div></section><div className="stack">{state.changes.map((c:any)=><section className="panel" key={c.id}><div className="panel-heading"><h3>Source change · {new Date(c.at).toLocaleString()}</h3><Status value={c.classification}/></div><p>{c.reason}</p><div className="impact-columns"><div><h4>Affected dependencies ({c.included.length})</h4>{c.included.map((n:any)=><p key={n.id}>{n.type}: {n.label}</p>)}</div><div><h4>Recorded non-impact ({c.excluded.length})</h4>{c.excluded.map((n:any)=><p key={n.id}>{n.label}<small>{n.reason}</small></p>)}</div></div></section>)}</div></>}
 {view==='markets'&&<><div className="row-actions"><button className="button small" onClick={()=>form('Record market / dossier context',[{name:'market',label:'Market / jurisdiction'},{name:'dossier',label:'Dossier identifier'},{name:'submittedState',label:'Recorded submitted state',value:'NOT_RECORDED'}],async v=>{await act({action:'market',...v,sourceIds:state.sources.filter((s:any)=>s.status==='PARSED').map((s:any)=>s.id)});},'This links current source IDs to the recorded market. It does not classify a legal filing obligation.')}><Plus size={15}/> Add market</button><button className="button small secondary" onClick={()=>form('Record an internal review inquiry',[{name:'title',label:'Internal review question (no authority outcome claim)',type:'textarea'},{name:'market',label:'Market / jurisdiction'}],async v=>{await act({action:'query',...v,fieldIds:state.fields.filter((f:any)=>f.status==='APPROVED').map((f:any)=>f.id)});},'This is an internal inquiry. For source-cited authority questions and evidenced outcomes, open Digital twin & lifecycle → HA questions.')}><Plus size={15}/> Add review inquiry</button><button className="button small secondary" onClick={()=>navigate('lifecycle')}>Source-cited HAQ workflow <ArrowRight size={15}/></button></div><div className="market-grid">{state.markets.map((m:any)=><article className="panel" key={m.id}><span className="eyebrow">{m.market}</span><h3>{m.dossier}</h3><p>{m.product}</p><Status value={m.classification}/><small>{m.sourceIds.length} source dependencies</small></article>)}</div><div className="stack">{state.queries.map((q:any)=><article className="panel" key={q.id}><div className="panel-heading"><h3>{q.title}</h3><Status value={q.status}/></div><p>{q.market} · {q.precedents.length} verified recorded precedents</p>{q.response.length?q.response.map((r:any)=><p className="statement" key={r.fieldId}>{r.text}</p>):<p className="callout">No approved supporting facts. Response remains an evidence gap.</p>}<p className="subnote">{q.limitation}</p>{q.status!=='APPROVED'&&<button className="button small secondary" onClick={()=>form('Review inquiry response',[{name:'reason',label:'Response review reason (not an authority outcome)',type:'textarea'}],async v=>{await act({action:'queryDecision',id:q.id,revision:q.revision,...v});},'An independent authorized human reviews the exact response revision. This review note does not establish an authority outcome or enter approved outcome memory.')} disabled={!canWrite}>Review response</button>}</article>)}</div></>}
